function minuteFromDay(value,businessDate){const d=dateObject(value),base=dateObject(businessDate);if(!d||!base)return null;return (d.getTime()-base.getTime())/60000}
function segmentClass(segment){const category=String(segment.category||"").toLowerCase(),status=String(segment.actual_status||"").toLowerCase(),mismatch=String(segment.mismatch||"").toLowerCase();if(mismatch.includes("time_off")||category.includes("pto")||category.includes("away"))return"pto";if(segment.is_gap)return"gap";if(category.includes("meal")||category.includes("lunch")||status.includes("meal"))return"meal";if(category.includes("break")||status.includes("break")||status.includes("personal"))return"break";if(category.includes("travel")||status.includes("travel"))return"travel";if(category.includes("productive")||status.includes("available")||status.includes("disponible")||status.includes("entrant")||status.includes("sortant"))return"logged";return"off"}
function timelineBoard(rows,onSelect){const root=node("div","timeline");if(!rows?.length){root.append(empty("No completed schedule-integrity case requires review."));return root}let min=1440,max=0;rows.forEach(row=>{for(const value of [row.scheduled_start,row.scheduled_end,...(row.segments||[]).flatMap(segment=>[segment.start,segment.end])]){const minute=minuteFromDay(value,row.date);if(minute!==null){min=Math.min(min,minute);max=Math.max(max,minute)}}});let startHour=Math.max(0,Math.floor(min/60)-1),endHour=Math.min(36,Math.ceil(max/60)+1);if(endHour-startHour<10)endHour=Math.min(36,startHour+10);const labels=[];for(let hour=startHour;hour<=endHour;hour+=Math.max(1,Math.ceil((endHour-startHour)/9)))labels.push(hour);const head=node("div","timehead");head.style.gridTemplateColumns=`175px repeat(${labels.length},1fr)`;head.append(node("span",null,"Agent / case"));labels.forEach(hour=>head.append(node("b",null,`${String(hour%24).padStart(2,"0")}:00`)));root.append(head);const total=(endHour-startHour)*60;rows.forEach((row,index)=>{const item=node("div",`case${index===0?" selected":""}`);item.onclick=()=>{root.querySelectorAll(".case").forEach(el=>el.classList.remove("selected"));item.classList.add("selected");onSelect(row)};const meta=node("div","case-meta");meta.append(node("b",null,row.agent||row.agent_id),node("small",null,`${row.management_lob||"Unmapped"} · ${time(row.scheduled_start)}–${time(row.scheduled_end)}`),node("em",null,`${row.classification||"Review"} · ${fmt(row.displaced_minutes,"integer")} min`));const tracks=node("div","tracks"),schedule=node("div","track"),actual=node("div","track");const addBand=(container,left,right,cls,title)=>{if(left===null||right===null)return;const band=node("i",cls);band.style.left=`${Math.max(0,(left-startHour*60)/total*100)}%`;band.style.width=`${Math.max(.15,(Math.min(right,endHour*60)-Math.max(left,startHour*60))/total*100)}%`;band.title=title;container.append(band)};addBand(schedule,minuteFromDay(row.scheduled_start,row.date),minuteFromDay(row.scheduled_end,row.date),"schedule",`Published ${time(row.scheduled_start)}–${time(row.scheduled_end)}`);(row.segments||[]).forEach(segment=>addBand(actual,minuteFromDay(segment.start,row.date),minuteFromDay(segment.end,row.date),segmentClass(segment),`${time(segment.start)}–${time(segment.end)} ${segment.actual_status||segment.category||""}`));tracks.append(node("label",null,"SHIFT"),schedule,node("label",null,"STATUS"),actual);item.append(meta,tracks);root.append(item)});return root}
function fillInspector(panel,row,gaps){while(panel.children.length>1)panel.lastChild.remove();if(!row){panel.append(empty("Select an agent-day from the review board."));return}const residual=(gaps||[]).filter(item=>item.agent_id===row.agent_id&&item.date===row.date);panel.append(sideList([["Published shift",`${time(row.scheduled_start)}–${time(row.scheduled_end)}`],["Observed span",`${time(row.observed_start)}–${time(row.observed_end)}`],["Classification",row.classification||"Review"],["Displaced time",`${fmt(row.displaced_minutes,"integer")} min`],["Residual fragments",String(residual.length)]]));if(residual.length)panel.append(note("EXACT RESIDUAL",residual.map(item=>`${time(item.start)}–${time(item.end)} (${item.minutes} min)`).join(" · ")));else panel.append(note("RECONCILED","No residual gap remains for this selected case."))}

