function queueMappingTable(rows){return makeTable(rows,[{key:"queue",label:"Queue",strong:true},{key:"primary_service_scope",label:"Primary data scope"},{key:"service_views",label:"Service Flash views"},{key:"service_related",label:"SL related",format:value=>value?"Yes":"No",pill:value=>value?"green":"blue"},{key:"workforce_owner",label:"Workforce owner"},{key:"designation",label:"Designation"},{key:"overlap",label:"View rule",pill:value=>value==="DUAL VIEW"?"amber":value==="SINGLE VIEW"?"green":"blue"}])}
function renderMappings(data){const shell=node("section","panel mapping-tabs"),nav=node("nav","mapping-nav"),body=node("article","mapping-body"),queues=node("button","on","Queue register"),service=node("button",null,"Service profiles"),capacity=node("button",null,"Capacity mappings"),buttons=[queues,service,capacity],activate=button=>{buttons.forEach(item=>item.classList.toggle("on",item===button))},showQueues=()=>{activate(queues);body.replaceChildren(node("h2",null,"Service and non-service queue register"),node("p",null,"Every mapped Call-by-Call queue, its exact Flash inclusion and its separate workforce ownership."),queueMappingTable(data.queue_register),note("FORD VL OWNERSHIP","Ford VL/DE queues remain visible in the combined RSA BE service view where configured, while their primary data scope and workforce owner remain Ford NL / Ford Dutch. This overlap does not move staffing into RSA BE."),note("NON-SERVICE DOES NOT MEAN DELETED","No rows stay available in clean governed data and diagnostics; they are excluded only from the service-level Flash total."))},showService=()=>{activate(service);body.replaceChildren(node("h2",null,"Service profiles"),node("p",null,"Exact call-queue membership and configured service target by Management LOB."),serviceMappingTable(data.service_profiles),note("SEPARATE GRAINS","RSA BE service is combined. Staffing LOBs remain separate for capacity preparation."))},showCapacity=()=>{activate(capacity);body.replaceChildren(node("h2",null,"Capacity mappings"),node("p",null,"Forecast Staff Type and published schedule assignment mapped to Planning Group and Management LOB."),capacityMappingTable(data.capacity_mappings),note("NO GUESSING","Unmapped Staff Types or assignments remain visible until the configuration is reviewed."))};queues.onclick=showQueues;service.onclick=showService;capacity.onclick=showCapacity;nav.append(queues,service,capacity);[["Service hash",data.hashes?.service_profiles],["Capacity hash",data.hashes?.capacity_mapping],["Metric hash",data.hashes?.metric_catalog]].forEach(item=>{const text=node("span",null,`${item[0]} · ${String(item[1]||"").slice(0,12)}`);nav.append(text)});shell.append(nav,body);showQueues();return shell}
function renderJobs(data){const grid=node("section","grid"),register=panel("JOB REGISTER","Refresh, report and analysis execution","CURRENT SESSION");register.append(makeTable(data.jobs,[{key:"started_at",label:"Started",format:dateTime},{key:"kind",label:"Type"},{key:"label",label:"Job",strong:true},{key:"status",label:"State",pill:value=>statusClass(value)},{key:"finished_at",label:"Finished",format:dateTime},{key:"job_id",label:"Run ID"}]));const current=data.jobs?.[0],detail=panel("SELECTED JOB",current?.label||"No active job",current?.status||"IDLE");if(current)detail.append(sideList([["Status",current.status,statusClass(current.status)==="red"?"neg":""],["Started",dateTime(current.started_at)],["Finished",dateTime(current.finished_at)],["Output",current.output||"—"],["Run ID",current.job_id||"—"]]),current.error?note("ERROR",current.error,true):note("EXECUTION BOUNDARY","Jobs operate on governed data. Source extracts remain read-only."));else detail.append(empty("No job has run in this console session."));const logs=panel("LOG REGISTER","Latest local execution logs","TECHNICAL DETAIL");logs.classList.add("full");logs.append(makeTable(data.logs,[{key:"modified_at",label:"Modified",format:dateTime},{key:"name",label:"Log file",strong:true},{key:"size_bytes",label:"Size",kind:"bytes",align:"right"}]));grid.append(register,detail,logs);return grid}

const renderers={desk:renderDesk,demand:renderDemand,capacity:renderCapacity,scenario:renderScenario,service:renderService,pulse:renderPulse,integrity:renderIntegrity,realisations:renderRealisations,absence:renderAbsence,patterns:renderPatterns,reports:renderReports,archive:renderArchive,readiness:renderReadiness,mappings:renderMappings,jobs:renderJobs};

async function loadView(){const workspace=$("workspace");workspace.replaceChildren();const loading=node("div","loading-card");loading.append(node("span","spinner"),node("b",null,"Reading governed marts"),node("small",null,"No raw extracts are opened by this screen."));workspace.append(loading);$("cards").replaceChildren();try{const data=await api(`/api/view/${state.page}?${query()}`);state.data=data;renderCards(data.cards);workspace.replaceChildren(renderers[state.page](data));const names={desk:"Manager Desk",demand:"Demand",capacity:"Capacity",scenario:"Scenario",service:"Service",pulse:"Attendance Pulse",integrity:"Schedule Integrity",realisations:"Realisations",absence:"Final Absence",patterns:"Patterns",reports:"Deliver",archive:"Archive",readiness:"Readiness",mappings:"Mappings",jobs:"Jobs"};$("scope-text").textContent=`${shortDate($("start").value)} → ${shortDate($("end").value)} · ${selected("lob")||"All Management LOBs"} · ${selected("planning")||"All Planning Groups"} · ${selected("leader")||"All Team Leaders"} · ${names[state.page]}`;}catch(error){workspace.replaceChildren();const failed=node("div","loading-card");failed.append(node("b",null,"This page could not be loaded"),node("small",null,error.message));workspace.append(failed);showToast(error.message,true)}}

async function loadMeta({preserve=false}={}){
  try{
    const current={lob:selected("lob"),planning:selected("planning"),staff:selected("staff"),leader:selected("leader"),agent:selected("agent"),period:$("period").value,start:$("start").value,end:$("end").value};
    state.meta=await api("/api/meta");
    $("data-through").textContent=`ACTUALS THROUGH ${shortDate(state.meta.latest_date).toUpperCase()}`;
    $("freshness-note").textContent=state.meta.last_refresh.status==="SUCCESS"?"DATABASE READY":"CHECK LAST UPDATE";
    $("state-dot").style.background=state.meta.last_refresh.status==="SUCCESS"?"#1f7a53":"#9c6400";
    $("footer-version").textContent=`WFMHub ${state.meta.version}`;
    setSelect("lob",state.meta.management_lobs,preserve?current.lob:null);
    cascade("lob");
    if(preserve){
      if(current.planning){$("planning").value=current.planning;cascade("planning")}
      if(current.staff){$("staff").value=current.staff;cascade("staff")}
      if(current.leader){$("leader").value=current.leader;cascade("leader")}
      if(current.agent)$("agent").value=current.agent;
      $("period").value=current.period;$("start").value=current.start;$("end").value=current.end;
    }else setPeriod("latest");
    const cut=(state.meta.sources||[]).filter(row=>row.newest_date).slice(0,5).map(row=>`${row.family} ${shortDate(row.newest_date)}`).join(" · ");
    $("source-cut").textContent=cut||"No source freshness available";
    go(state.page,{load:true});
  }catch(error){showToast(error.message,true);$("workspace").replaceChildren(empty(error.message))}
}

async function startUpdate(){const dialog=$("update-dialog");if(!dialog.open)dialog.showModal();try{await api("/api/refresh",{method:"POST",headers:{"Content-Type":"application/json","X-WFMHub-Action":"refresh"},body:"{}"})}catch(error){if(!error.message.includes("409"))showToast(error.message,true)}pollUpdate()}
async function pollUpdate(){clearTimeout(state.refreshTimer);try{const job=await api("/api/refresh");$("update-status").textContent=job.status==="RUNNING"?"Ingesting, validating and rebuilding governed marts…":`Update ${job.status.toLowerCase()}`;$("update-log").textContent=(job.lines||[]).join("\n");$("update-log").scrollTop=$("update-log").scrollHeight;$("progress-bar").style.width=job.status==="RUNNING"?`${Math.min(88,12+(job.lines||[]).length*2.5)}%`:"100%";$("progress-bar").style.background=job.status==="ERROR"?"#b42318":"#007c83";if(job.status==="RUNNING")state.refreshTimer=setTimeout(pollUpdate,1400);else if(job.status!=="IDLE"){await loadMeta({preserve:true});showToast(job.status==="SUCCESS"?"WFMHub data updated":"Update failed; inspect Jobs & Logs",job.status!=="SUCCESS")}}catch(error){showToast(error.message,true)}}
async function startAction(kind,payload){const dialog=$("job-dialog");$("job-title").textContent=kind==="report"?"Generating workbook":"Running analysis";$("job-status").textContent="Starting local job…";$("job-log").textContent="";$("job-progress").style.width="8%";$("job-download").classList.add("hidden");if(!dialog.open)dialog.showModal();try{await api(`/api/actions/${kind}`,{method:"POST",headers:{"Content-Type":"application/json","X-WFMHub-Action":kind},body:JSON.stringify(payload)});pollAction()}catch(error){$("job-status").textContent=error.message;showToast(error.message,true)}}
async function pollAction(){clearTimeout(state.jobTimer);try{const job=await api("/api/actions");$("job-status").textContent=job.status==="RUNNING"?`${job.label||"Output"} is running…`:job.status==="SUCCESS"?"Output ready":"Output failed";$("job-log").textContent=(job.lines||[]).join("\n");$("job-progress").style.width=job.status==="RUNNING"?"68%":"100%";$("job-progress").style.background=job.status==="ERROR"?"#b42318":"#007c83";if(job.output){$("job-download").href=`/api/download?file=${encodeURIComponent(job.output)}`;$("job-download").classList.remove("hidden")}if(job.status==="RUNNING")state.jobTimer=setTimeout(pollAction,1000);else{if(state.page==="reports"||state.page==="archive"||state.page==="jobs")loadView();showToast(job.status==="SUCCESS"?"Output ready":job.error||"Output failed",job.status!=="SUCCESS")}}catch(error){showToast(error.message,true)}}

document.addEventListener("DOMContentLoaded",()=>{const initial=location.hash.slice(1).split("?")[0];if(pages[initial])state.page=initial;$("period").addEventListener("change",()=>{setPeriod($("period").value);loadView()});["start","end"].forEach(id=>$(id).addEventListener("change",()=>{$("period").value="custom";loadView()}));["lob","planning","staff","leader","agent"].forEach(id=>$(id).addEventListener("change",()=>{cascade(id);loadView()}));$("reset-btn").onclick=()=>{$("period").value="latest";setSelect("lob",state.meta.management_lobs,null);cascade("lob");setPeriod("latest");loadView()};$("export-btn").onclick=()=>{location.href=`/api/export/${state.page}?${query()}`};$("generate-btn").onclick=()=>go("reports");$("update-btn").onclick=startUpdate;$("dialog-close").onclick=()=>$("update-dialog").close();$("job-close").onclick=()=>$("job-dialog").close();loadMeta()});
